const raw = $json.message?.content;
let p; try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, error: 'JSON parse failed: ' + e.message } }]; }
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < (s||'').length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
const valid = p.solutionMarkdown && p.solutionMarkdown.startsWith('# Solution Architecture:');
return [{ json: {
  valid,
  integrationStyle: p.integrationStyle || 'rest_only',
  solutionMarkdown: p.solutionMarkdown || '',
  openapiYaml: p.openapiYaml || null,
  asyncapiYaml: p.asyncapiYaml || null,
  avroSchemasJson: p.avroSchemasJson || null,
  cloudEventsMarkdown: p.cloudEventsMarkdown || null,
  sqlSchemaSql: p.sqlSchemaSql || '',
  hashes: {
    solution: fnv1a(p.solutionMarkdown),
    openapi: fnv1a(p.openapiYaml),
    asyncapi: fnv1a(p.asyncapiYaml),
    avro: fnv1a(JSON.stringify(p.avroSchemasJson)),
    cloudEvents: fnv1a(p.cloudEventsMarkdown),
    sql: fnv1a(p.sqlSchemaSql)
  }
} }];

const j = $json;
if (!j.valid) return [];
const ctx = $('Pass Context').first().json;
const meta = { jobId: ctx.jobId, stage: 'solution-architecture', integrationStyle: j.integrationStyle };
const out = [];

// Always include solution architecture markdown
out.push({ json: { artifactType: 'solution_arch_md', content: { markdown: j.solutionMarkdown }, contentHash: j.hashes.solution, meta } });

// REST artifacts
if (j.openapiYaml) out.push({ json: { artifactType: 'openapi_yaml', content: { yaml: j.openapiYaml }, contentHash: j.hashes.openapi, meta } });

// Event-driven artifacts
if (j.asyncapiYaml) out.push({ json: { artifactType: 'asyncapi_yaml', content: { yaml: j.asyncapiYaml }, contentHash: j.hashes.asyncapi, meta } });
if (j.avroSchemasJson) out.push({ json: { artifactType: 'avro_schemas_json', content: { schemas: j.avroSchemasJson }, contentHash: j.hashes.avro, meta } });
if (j.cloudEventsMarkdown) out.push({ json: { artifactType: 'cloud_events_md', content: { markdown: j.cloudEventsMarkdown }, contentHash: j.hashes.cloudEvents, meta } });

// Database artifacts
if (j.sqlSchemaSql) out.push({ json: { artifactType: 'sql_schema_sql', content: { sql: j.sqlSchemaSql }, contentHash: j.hashes.sql, meta } });

return out;

const ctx = $('Pass Context').first().json;
const sol = $('Validate Solution').first().json;
const enrichedSeq = $('Merge Change Assessment').first().json.enrichedSequencesArtifact || {};
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;
const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const remote = 'git@github.com:shlapolosa/software-delivery.git';

// Helper to safely escape heredoc content
const safeHeredoc = (content, marker) => {
  if (!content) return '';
  return String(content).replace(new RegExp(marker, 'g'), marker + '_ESCAPED');
};

let sh = `set -e
mkdir -p /opt/workspace

if [ ! -d '${repoDir}/.git' ]; then
  git clone '${remote}' '${repoDir}'
fi
cd '${repoDir}'
git fetch origin --prune

git checkout -B '${projectSlug}' 'origin/${projectSlug}' 2>/dev/null || git checkout -B '${projectSlug}'
mkdir -p '${projectDir}/docs' '${projectDir}/api' '${projectDir}/db'
`;

// Solution Architecture markdown
sh += `cat > '${projectDir}/docs/solution-architecture.md' <<'EOFSOL_${jobId}'
${safeHeredoc(sol.solutionMarkdown, 'EOFSOL_' + jobId)}
EOFSOL_${jobId}
`;

// Enriched Sequences JSON
if (enrichedSeq.enrichedSequences) {
  sh += `cat > '${projectDir}/docs/enriched-sequences.json' <<'EOFSEQ_${jobId}'
${safeHeredoc(JSON.stringify(enrichedSeq, null, 2), 'EOFSEQ_' + jobId)}
EOFSEQ_${jobId}
`;
}

// REST API spec
if (sol.openapiYaml) {
  sh += `cat > '${projectDir}/api/openapi.yaml' <<'EOFAPI_${jobId}'
${safeHeredoc(sol.openapiYaml, 'EOFAPI_' + jobId)}
EOFAPI_${jobId}
`;
}

// Event-driven specs
if (sol.asyncapiYaml) {
  sh += `cat > '${projectDir}/api/asyncapi.yaml' <<'EOFASYNC_${jobId}'
${safeHeredoc(sol.asyncapiYaml, 'EOFASYNC_' + jobId)}
EOFASYNC_${jobId}
`;
}

if (sol.avroSchemasJson) {
  sh += `cat > '${projectDir}/api/avro-schemas.json' <<'EOFAVRO_${jobId}'
${safeHeredoc(JSON.stringify(sol.avroSchemasJson, null, 2), 'EOFAVRO_' + jobId)}
EOFAVRO_${jobId}
`;
}

if (sol.cloudEventsMarkdown) {
  sh += `cat > '${projectDir}/docs/cloud-events.md' <<'EOFCE_${jobId}'
${safeHeredoc(sol.cloudEventsMarkdown, 'EOFCE_' + jobId)}
EOFCE_${jobId}
`;
}

// Database schema
if (sol.sqlSchemaSql) {
  sh += `cat > '${projectDir}/db/schema.sql' <<'EOFSQL_${jobId}'
${safeHeredoc(sol.sqlSchemaSql, 'EOFSQL_' + jobId)}
EOFSQL_${jobId}
`;
}

sh += `
git add '${projectSlug}-docs'
git commit -m 'Add solution architecture for ${projectSlug} (job ${jobId})' || true
git push -u origin '${projectSlug}'
`;

return [{ json: { ...ctx, integrationStyle: sol.integrationStyle, enrichedSequences: enrichedSeq, gitScript: sh } }];

const ctx = $('Pass Context').first().json;
const sol = $('Validate Solution').first().json;
const enrichedSeq = $('Merge Change Assessment').first().json.enrichedSequencesArtifact || {};
return [{ json: {
  success: true,
  jobId: ctx.jobId,
  projectSlug: ctx.projectSlug,
  stage: 'solution-architecture',
  integrationStyle: sol.integrationStyle,
  enrichedSequences: {
    totalTickets: enrichedSeq.overallSummary?.totalTickets || 0,
    byPriority: enrichedSeq.overallSummary?.byPriority || {},
    byType: enrichedSeq.overallSummary?.byType || {}
  },
  artifacts: {
    solutionArch: ctx.projectSlug + '-docs/docs/solution-architecture.md',
    enrichedSequences: ctx.projectSlug + '-docs/docs/enriched-sequences.json',
    openapi: sol.openapiYaml ? ctx.projectSlug + '-docs/api/openapi.yaml' : null,
    asyncapi: sol.asyncapiYaml ? ctx.projectSlug + '-docs/api/asyncapi.yaml' : null,
    avroSchemas: sol.avroSchemasJson ? ctx.projectSlug + '-docs/api/avro-schemas.json' : null,
    cloudEvents: sol.cloudEventsMarkdown ? ctx.projectSlug + '-docs/docs/cloud-events.md' : null,
    sqlSchema: sol.sqlSchemaSql ? ctx.projectSlug + '-docs/db/schema.sql' : null
  }
} }];
